import {FACE_CENTERS} from './lobby-art.mjs?v=20261030-duel12';
import {SOLO_NAMES,experience} from './campaign-growth-data.mjs';
const colors={fire:'#d67942',nature:'#91af65',frost:'#9dcfdf',lightning:'#dbc07c',shadow:'#aa8cc2',star:'#8ea9d4'};
let serial=0;
function portrait(hero){const [x,y]=FACE_CENTERS[hero]||FACE_CENTERS.fire;return `<span class="hero-choice-portrait" style="--choice-color:${colors[hero]||colors.fire}"><svg viewBox="${x-40} ${y-40} 80 80" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><image href="assets/lobby/hero-splashes-v1.png" width="1536" height="1024"/></svg></span>`;}
export function enhanceHeroPickers(root,profile){
 for(const select of root.querySelectorAll('select[data-hero-view],select[data-gear-target],select#transfer-target,select#choice-hero')){
  if(select.closest('[data-hero-picker]'))continue;
  const options=[...select.options],chosen=options.find(o=>o.selected),hero=chosen?.value,label=select.matches('[data-hero-view]')?'切换角色':select.id==='transfer-target'?'接收功力':select.id==='choice-hero'?'选择英雄':'装备给谁',id='hero-choice-'+(++serial),wrapper=document.createElement('div');wrapper.className='hero-picker';wrapper.dataset.heroPicker='';
  select.before(wrapper);wrapper.append(select);select.hidden=true;select.tabIndex=-1;select.setAttribute('aria-hidden','true');
  const trigger=document.createElement('button');trigger.type='button';trigger.className='hero-picker-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls',id);trigger.setAttribute('aria-label',label+'：'+(SOLO_NAMES[hero]||'暂无可选英雄'));trigger.disabled=select.disabled||!options.some(o=>!o.disabled&&SOLO_NAMES[o.value]);trigger.innerHTML=portrait(hero)+`<span><small>${label}</small><strong>${SOLO_NAMES[hero]||'暂无可选英雄'}</strong></span><i aria-hidden="true">⌄</i>`;
  wrapper.append(trigger);const menu=document.createElement('div');menu.id=id;menu.className='hero-picker-menu';menu.setAttribute('popover','auto');menu.setAttribute('role','listbox');menu.setAttribute('aria-label',label);
  menu.innerHTML=options.filter(o=>SOLO_NAMES[o.value]).map(o=>`<button type="button" role="option" data-hero-choice="${o.value}" aria-selected="${o.selected}" ${o.disabled?'disabled':''}>${portrait(o.value)}<strong>${SOLO_NAMES[o.value]}</strong><small>${profile.heroes[o.value]?'Lv.'+experience(profile.heroes[o.value].exp).level:'尚未拥有'}${o.disabled?' · 不可选':''}</small></button>`).join('');wrapper.append(menu);
  trigger.addEventListener('click',()=>{if(menu.matches(':popover-open')){menu.hidePopover();return;}const r=trigger.getBoundingClientRect(),width=Math.min(330,innerWidth-24);menu.style.width=width+'px';menu.style.left=Math.max(12,Math.min(innerWidth-width-12,r.left))+'px';menu.style.top=Math.min(innerHeight-230,Math.max(12,r.bottom+8))+'px';menu.showPopover();trigger.setAttribute('aria-expanded','true');(menu.querySelector('[aria-selected="true"]:not(:disabled)')||menu.querySelector('button:not(:disabled)'))?.focus();});
  menu.addEventListener('toggle',()=>trigger.setAttribute('aria-expanded',String(menu.matches(':popover-open'))));
  menu.addEventListener('click',event=>{const button=event.target.closest('[data-hero-choice]');if(!button||button.disabled)return;menu.hidePopover();select.value=button.dataset.heroChoice;select.dispatchEvent(new Event('change',{bubbles:true}));if(select.isConnected){const name=SOLO_NAMES[select.value];trigger.innerHTML=portrait(select.value)+`<span><small>${label}</small><strong>${name}</strong></span><i aria-hidden="true">⌄</i>`;trigger.setAttribute('aria-label',label+'：'+name);for(const b of menu.querySelectorAll('[data-hero-choice]'))b.setAttribute('aria-selected',String(b.dataset.heroChoice===select.value));trigger.focus();}});
  menu.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;const buttons=[...menu.querySelectorAll('button:not(:disabled)')],current=buttons.indexOf(document.activeElement),step=event.key==='ArrowUp'?-3:event.key==='ArrowDown'?3:event.key==='ArrowLeft'?-1:1,index=event.key==='Home'?0:event.key==='End'?buttons.length-1:(current+step+buttons.length)%buttons.length;event.preventDefault();buttons[index]?.focus();});
 }
}
